//! Autogenerated upstream weights for `zrml_parimutuel`.
//! `zrml_parimutuel` 的上游自动生成权重。
//!
//! Generated with Substrate benchmark CLI 48.0.0 on 2025-07-11.
//! These values are retained for the Phase 1 port and must be regenerated for Nexus production.
//! 这些数值在第一阶段移植中保留，Nexus 生产接线前必须重新生成。

#![allow(unused_parens)]
#![allow(unused_imports)]

use core::marker::PhantomData;
use frame_support::{traits::Get, weights::Weight};

/// Weight functions required by the parimutuel pallet.
/// 彩池制 pallet 所需的权重函数。
pub trait WeightInfoZeitgeist {
    fn buy() -> Weight;
    fn claim_rewards() -> Weight;
    fn claim_refunds() -> Weight;
}

/// Upstream benchmark-derived weight implementation.
/// 基于上游基准测试生成的权重实现。
pub struct WeightInfo<T>(PhantomData<T>);

impl<T: frame_system::Config> WeightInfoZeitgeist for WeightInfo<T> {
    fn buy() -> Weight {
        Weight::from_parts(119_072_000, 4173)
            .saturating_add(T::DbWeight::get().reads(4))
            .saturating_add(T::DbWeight::get().writes(3))
    }

    fn claim_rewards() -> Weight {
        Weight::from_parts(121_283_000, 4173)
            .saturating_add(T::DbWeight::get().reads(4))
            .saturating_add(T::DbWeight::get().writes(3))
    }

    fn claim_refunds() -> Weight {
        Weight::from_parts(112_452_000, 6054)
            .saturating_add(T::DbWeight::get().reads(5))
            .saturating_add(T::DbWeight::get().writes(3))
    }
}
